const LOOKUP = new Map(PAIRS.map((p) => [p.heard.toLowerCase(), p]));

function stripWord(w) {
  return String(w).replace(/^[^A-Za-zÀ-ÿ0-9]+|[^A-Za-zÀ-ÿ0-9]+$/g, '');
}
function firstWordOf(alt) { return stripWord(String(alt).trim().split(/\s+/)[0] || ''); }
function lastWordOf(alt) {
  const parts = String(alt).trim().split(/\s+/);
  return stripWord(parts[parts.length - 1] || '');
}

export function correctWithLog(t) {
  const src = String(t);
  const entries = new Map();
  function log(hit, mode, term, cue) {
    const key = hit.heard + '|' + mode + '|' + term + '|' + (cue || '');
    const prev = entries.get(key);
    if (prev) prev.count += 1;
    else entries.set(key, { heard: hit.heard, term, count: 1, mode, cue: cue || null });
  }
  let out = '';
  let last = 0;
  let m;
  PATTERN.lastIndex = 0;
  while ((m = PATTERN.exec(src)) !== null) {
    const hit = LOOKUP.get(m[0].toLowerCase());
    if (!hit) continue;
    const matchStart = m.index;
    const matchEnd = m.index + m[0].length;
    let replacement = null;
    let mode = hit.cls;
    let term = hit.cls === 'slash' ? hit.alts.join('/') : hit.term;
    let cue = null;
    let absorbEnd = matchEnd;
    let absorbBefore = null;
    if (hit.cls === 'slash' && hit.ctx) {
      const fm = src.slice(matchEnd).match(/^\s+([A-Za-zÀ-ÿ0-9'’-]+)/);
      if (fm) {
        const cueWord = stripWord(fm[1]);
        const matches = hit.alts.filter(
          (a) => lastWordOf(a).toLowerCase() === cueWord.toLowerCase());
        if (cueWord && matches.length === 1) {
          replacement = matches[0];
          term = matches[0];
          cue = cueWord;
          absorbEnd = matchEnd + fm[0].length;
        }
      }
      if (replacement === null) {
        const gapSoFar = src.slice(last, matchStart);
        const bm = gapSoFar.match(/([A-Za-zÀ-ÿ0-9'’-]+)([.,;:!?]?\s*)$/);
        if (bm) {
          const cueWord = stripWord(bm[1]);
          const matches = hit.alts.filter(
            (a) => firstWordOf(a).toLowerCase() === cueWord.toLowerCase());
          if (cueWord && matches.length === 1) {
            replacement = matches[0];
            term = matches[0];
            cue = cueWord;
            absorbBefore = bm;
          }
        }
      }
      if (replacement !== null) mode = 'context';
    }
    let skipLog = false;
    if (replacement === null) {
      if (hit.cls === 'certain' && hit.term === hit.heard) {
        // Identity pair (the listed term is the listed heard form):
        // any match is already the term, in whatever case it was
        // transcribed; not a correction, and the case is preserved.
        replacement = m[0];
        skipLog = true;
      } else if (hit.cls === 'certain'
        && hit.term.toLowerCase().startsWith(m[0].toLowerCase())
        && hit.term.length > m[0].length) {
        // The term extends the heard form (arrhenius -> Arrhenius
        // equation). If the transcript already continues with the
        // term's own continuation, the phrase is already correct and
        // must not be extended a second time.
        const cont = hit.term.slice(m[0].length);
        if (src.slice(matchEnd, matchEnd + cont.length).toLowerCase() === cont.toLowerCase()) {
          replacement = m[0];
          skipLog = true;
        }
      }
      if (replacement === null) {
        replacement = hit.cls === 'slash' ? m[0] + '/' + hit.alts.join('/') : hit.term;
      }
    }
    let gap = src.slice(last, matchStart);
    if (absorbBefore) {
      gap = gap.slice(0, absorbBefore.index) + absorbBefore[2];
      gap = gap.replace(/\s+$/, '');
      if (gap) gap += ' ';
    }
    out += gap + replacement;
    last = absorbEnd;
    if (!skipLog) log(hit, mode, term, cue);
  }
  out += src.slice(last);
  const applied = [...entries.values()];
  return {
    text: out,
    applied,
    appliedCertain: applied.filter((a) => a.mode === 'certain'),
    appliedSlash: applied.filter((a) => a.mode === 'slash'),
    appliedContext: applied.filter((a) => a.mode === 'context'),
  };
}

export function correctText(t) {
  return correctWithLog(t).text;
}
